import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { JSDOM } from 'jsdom';

// The markup and the messages are the server's: generated by the Go test
// handlers/resource TestTransferStatusFixturesAreCurrent from the real
// partial and services/statusview.Build -- a block that changed shape there
// fails here instead of on the page.
const PAGE = readFileSync(new URL('./__fixtures__/transfer-status-page.html', import.meta.url), 'utf8');
const STATES = JSON.parse(readFileSync(new URL('./__fixtures__/transfer-status-states.json', import.meta.url), 'utf8'));
const byDesign = Object.fromEntries(STATES.map((s) => [s.design, s]));

const dom = new JSDOM('<!doctype html><html lang="ru"><body></body></html>', { url: 'https://webtor.io/' });
global.window = dom.window;
global.document = dom.window.document;

const {
    present, applyView, bindBlock, paintBar, mirrorBlock, initDetails, upsellElsewhere, createCtaWatch, safeHref, ctaProps,
    playing, holesMask, NAVBAR_H,
} = await import('./transferStatus.js');

function page() {
    document.body.innerHTML = PAGE;
    const block = document.querySelector('#torrent-status [data-tx]');
    return { block, refs: bindBlock(block) };
}

// Everything a viewer can see or a script can read of the block's slots:
// the mode (chain or badge), visibility, the state attributes, the icon, the
// text. The bar is left out -- the server never has the cells, the stream
// brings them (paintBar's own test).
function snapshot(block) {
    const out = { key: block.getAttribute('data-key'), mode: block.getAttribute('data-mode'), sticky: block.hasAttribute('data-sticky') };
    const slot = (el) => ({
        hidden: el.hidden,
        tone: el.getAttribute('data-tone'),
        kind: el.getAttribute('data-kind'),
        dim: el.hasAttribute('data-dim'),
        moving: el.hasAttribute('data-moving'),
        dots: el.hasAttribute('data-dots'),
        icon: el.querySelector('.tx-ic use') ? el.querySelector('.tx-ic use').getAttribute('href') : null,
        text: el.hidden ? '' : el.textContent.replace(/\s+/g, ' ').trim(),
    });
    out.nodes = Array.from(block.querySelectorAll('[data-tx-node]')).map(slot);
    out.segs = Array.from(block.querySelectorAll('[data-tx-seg]')).map(slot);
    const badge = block.querySelector('[data-tx-badge]');
    out.badge = {
        tone: badge.getAttribute('data-tone'),
        icon: badge.getAttribute('data-icon'),
        pulse: badge.hasAttribute('data-pulse'),
        use: badge.querySelector('.tx-bi use').getAttribute('href'),
        text: badge.textContent.replace(/\s+/g, ' ').trim(),
    };
    out.hint = slot(block.querySelector('[data-tx-hint]'));
    const vault = block.querySelector('[data-tx-vault]');
    out.vault = vault ? { hidden: vault.hidden, href: vault.getAttribute('href') } : null;
    out.rows = Array.from(block.querySelectorAll('[data-tx-row]')).map(slot);
    out.boxes = Array.from(block.querySelectorAll('[data-tx-pbox]')).map((el) => {
        const a = el.querySelector('[data-tx-cta]');
        return { ...slot(el), href: el.hidden ? null : a.getAttribute('href'), props: el.hidden ? null : ctaProps(a) };
    });
    out.detailsPlan = block.querySelector('[data-tx-dplan]').hidden;
    return out;
}

function render(refs, st, env = {}) {
    const view = st.status.view;
    const pres = present(view, { player: st.player, stallSub: st.stallSub, overCap: !!st.overCap, ...env });
    applyView(refs, view, pres, 'card');
    paintBar(refs, view, st.status);
    return pres;
}

test('every state: the page block updated in place ends exactly where a fresh server render would', () => {
    const ssrStates = STATES.filter((s) => s.ssr);
    assert.ok(ssrStates.length >= 25, `${ssrStates.length} states with a server render`);
    assert.ok(ssrStates.some((s) => s.status.view.mode === 'badge') && ssrStates.some((s) => s.status.view.mode === 'chain'), 'both modes');
    for (const st of ssrStates) {
        const { block, refs } = page();
        render(refs, st);
        const fresh = new JSDOM(`<!doctype html><body>${st.ssr}</body>`).window.document.querySelector('[data-tx]');
        assert.deepEqual(snapshot(block), snapshot(fresh), st.design);
    }
});

test('one block through every state and back: no element added or removed, the animated parts are the same nodes', async () => {
    const { block, refs } = page();
    // The first bar makes the cells (once); from here on nothing may be made.
    render(refs, byDesign.active);
    assert.equal(refs.cells.length, 256, 'the cells, made once');
    const before = Array.from(block.querySelectorAll('*'));
    const lines = Array.from(block.querySelectorAll('.tx-ln'));
    const labels = Array.from(block.querySelectorAll('.tx-sp'));
    const heads = Array.from(block.querySelectorAll('.tx-hd'));
    const ctas = Array.from(block.querySelectorAll('[data-tx-cta]'));
    const cells = refs.cells.slice();

    const added = [];
    const removed = [];
    const mo = new dom.window.MutationObserver((records) => {
        for (const r of records) {
            added.push(...Array.from(r.addedNodes).filter((n) => n.nodeType === 1));
            removed.push(...Array.from(r.removedNodes).filter((n) => n.nodeType === 1));
        }
    });
    mo.observe(block, { childList: true, subtree: true });

    const order = [...STATES, ...STATES.slice().reverse(), byDesign.tier_dl, byDesign.stream_stall, byDesign.stream_ok, byDesign.tier_dl];
    for (const st of order) {
        render(refs, st);
        await Promise.resolve(); // let the observer deliver
        const now = Array.from(block.querySelectorAll('*'));
        assert.equal(now.length, before.length, `${st.design}: element count`);
        assert.ok(now.every((el, i) => el === before[i]), `${st.design}: the same elements, in the same order`);
    }
    mo.disconnect();
    assert.deepEqual(added, [], 'no element was added');
    assert.deepEqual(removed, [], 'no element was removed');
    assert.ok(Array.from(block.querySelectorAll('.tx-ln')).every((el, i) => el === lines[i]), 'lines kept');
    assert.ok(Array.from(block.querySelectorAll('.tx-sp')).every((el, i) => el === labels[i]), 'labels kept');
    assert.ok(Array.from(block.querySelectorAll('.tx-hd')).every((el, i) => el === heads[i]), 'arrowheads kept');
    assert.ok(Array.from(block.querySelectorAll('[data-tx-cta]')).every((el, i) => el === ctas[i]), 'buttons kept');
    assert.ok(refs.cells.every((c, i) => c === cells[i]), 'piece cells kept');
});

// Nothing moves: the badge, where the chain was -- the same row, both kept
// in the block, only the mode switching. The chain the moment anything
// moves again.
test('chain and badge share the row: the mode switches, no element comes or goes', () => {
    const { block, refs } = page();
    render(refs, byDesign.active);
    const chain = block.querySelector('[data-tx-toggle]');
    const badge = block.querySelector('[data-tx-badge]');
    const head = block.querySelector('.tx-head');
    assert.equal(chain.parentElement, head);
    assert.equal(badge.parentElement, head, 'one row for both');
    assert.equal(block.getAttribute('data-mode'), 'chain');
    render(refs, byDesign.paused);
    assert.equal(block.getAttribute('data-mode'), 'badge');
    assert.equal(block.querySelector('[data-tx-toggle]'), chain, 'the chain is kept');
    assert.equal(block.querySelector('[data-tx-badge]'), badge);
    assert.equal(badge.getAttribute('data-tone'), 'warn');
    assert.equal(badge.getAttribute('data-icon'), 'pause');
    assert.equal(badge.querySelector('.tx-bi use').getAttribute('href'), '#tx-b-pause');
    assert.equal(badge.textContent.replace(/\s+/g, ' ').trim(), 'Кэширование на паузе 43% (14 сидов)');
    assert.equal(block.querySelector('[data-tx-htext]').textContent, byDesign.paused.status.view.hint, 'the state\'s hint under the badge');
    assert.equal(block.hasAttribute('data-sticky'), false, 'no sticky bar for a badge');
    render(refs, byDesign.checking);
    assert.equal(badge.getAttribute('data-icon'), 'dots');
    assert.equal(badge.hasAttribute('data-pulse'), false);
    render(refs, byDesign.vault_waiting);
    assert.equal(badge.hasAttribute('data-pulse'), true, 'Vault waiting pulses');
    render(refs, byDesign.cached_flow);
    assert.equal(block.getAttribute('data-mode'), 'chain', 'back at once');
    assert.equal(block.querySelectorAll('[data-tx-node]')[0].hidden, true, 'from the cache: no swarm');
});

// The mask: a band per run of missing cells, runs at the ends included.
test('holesMask: one band per run, none without holes', () => {
    assert.equal(holesMask(null, 8), '');
    assert.equal(holesMask(new Uint8Array([0]), 8), '');
    assert.equal(holesMask(new Uint8Array([0b10000001]), 8), 'linear-gradient(90deg, transparent 0%, #000 0% 12.5%, transparent 12.5%, transparent 87.5%, #000 87.5% 100%, transparent 100%)');
    assert.equal(holesMask(new Uint8Array([0b00111100]), 8), 'linear-gradient(90deg, transparent 25%, #000 25% 75%, transparent 75%)');
    assert.equal(holesMask(new Uint8Array([0xff]), 3), 'linear-gradient(90deg, transparent 0%, #000 0% 100%, transparent 100%)', 'bits past n ignored');
});

// Focus that was on the chain, or in its details, does not fall to <body>
// when the chain gives way to the badge -- a change the viewer did not make,
// ten seconds of stillness: the badge takes it, and gives it back to the
// chain when the chain returns. No node comes or goes for it.
test('focus stays in the block across chain → badge → chain', () => {
    const { block, refs } = page();
    render(refs, byDesign.active);
    const before = Array.from(block.querySelectorAll('*'));
    const { toggle } = refs;
    const badge = refs.badge.el;
    assert.equal(badge.getAttribute('tabindex'), '-1', 'no tab stop of its own');
    toggle.focus();
    assert.equal(document.activeElement, toggle);
    render(refs, byDesign.paused);
    assert.equal(document.activeElement, badge, 'the badge took it');
    render(refs, byDesign.missing_idle);
    assert.equal(document.activeElement, badge, 'badge to badge: it stays');
    render(refs, byDesign.caching_only);
    assert.equal(document.activeElement, toggle, 'back on the chain');
    // In the details (the close button), the same.
    refs.details.querySelector('[data-tx-close]').focus();
    render(refs, byDesign.cached);
    assert.equal(document.activeElement, badge);
    render(refs, byDesign.cached_flow);
    assert.equal(document.activeElement, toggle);
    // Focus elsewhere on the page is none of the block's business.
    const outside = document.createElement('button');
    document.body.appendChild(outside);
    outside.focus();
    render(refs, byDesign.paused);
    assert.equal(document.activeElement, outside);
    render(refs, byDesign.active);
    assert.equal(document.activeElement, outside);
    outside.remove();
    const after = Array.from(block.querySelectorAll('*'));
    assert.equal(after.length, before.length);
    assert.ok(after.every((el, i) => el === before[i]), 'the same nodes');
});

// The details popover belongs to the chain: when the chain gives way to the
// badge, an open popover closes with it.
test('the badge takes over: the chain\'s details close', () => {
    const { refs } = page();
    render(refs, byDesign.active);
    let closes = 0;
    refs.details.addEventListener('tx-close', () => { closes++; });
    render(refs, byDesign.caching_only);
    assert.equal(closes, 0, 'still the chain');
    render(refs, byDesign.paused);
    assert.equal(closes, 1, 'closed with the chain');
    render(refs, byDesign.cached);
    assert.equal(closes, 1, 'once: it is closed already');
});

// Pieces nobody connected has are hatched, whatever the mode: under the
// chain while the viewer waits on them, under the badge while nothing moves.
test('the piece bar hatches what nobody has, over the pulse, in both modes', () => {
    const { refs } = page();
    render(refs, byDesign.missing);
    const cells = refs.cells;
    // One hatch across the whole bar, shown over the missing runs (style.css
    // .tx-pbar::before): a band per run, as a share of the bar.
    assert.equal(refs.cellsHost.hasAttribute('data-holes'), true);
    assert.equal(refs.cellsHost.style.getPropertyValue('--tx-holes'),
        'linear-gradient(90deg, transparent 46.875%, #000 46.875% 60.9375%, transparent 60.9375%, ' +
        'transparent 75%, #000 75% 87.8906%, transparent 87.8906%)');
    // debugHoles: 47-61% and 75-88% of 256 cells.
    const holes = (i) => (i >= 120 && i < 156) || (i >= 192 && i < 225);
    assert.ok(cells.every((c, i) => c.classList.contains('m') === holes(i)), 'the holes hatched, nothing else');
    assert.equal(cells[100].classList.contains('a'), true, 'the fetching cells still pulse');
    render(refs, byDesign.missing_idle);
    assert.equal(refs.bar.getAttribute('data-mode'), 'pieces');
    assert.equal(cells[130].classList.contains('m'), true, 'under the badge too');
    render(refs, byDesign.active);
    assert.ok(cells.every((c) => !c.classList.contains('m')), 'gone with the holes');
    assert.equal(refs.cellsHost.hasAttribute('data-holes'), false);
    assert.equal(refs.cellsHost.style.getPropertyValue('--tx-holes'), '');
    // A cell both fetched and missing is hatched: nobody has the piece.
    const both = structuredClone(byDesign.missing);
    const act = new Uint8Array(32);
    act[15] = 0xff; // cells 120..127
    both.status.active = btoa(String.fromCharCode(...act));
    render(refs, both);
    assert.equal(cells[121].classList.contains('m'), true);
    assert.equal(cells[121].classList.contains('a'), false, 'the hatch, not the pulse');
});

// Where the pieces nobody has are the story, the hint ends with the way to
// have them fetched anyway: the page's own Vault link, shown only then.
test('the hint offers Vault only where pieces are missing', () => {
    const { block, refs } = page();
    const link = block.querySelector('[data-tx-vault]');
    assert.ok(link, 'the page has the link (Vault configured)');
    render(refs, byDesign.active);
    assert.equal(link.hidden, true);
    render(refs, byDesign.missing_idle);
    assert.equal(link.hidden, false);
    assert.equal(block.querySelector('[data-tx-htext]').textContent, byDesign.missing_idle.status.view.hint);
    assert.equal(link.parentElement, refs.hint, 'in the hint, after its words');
    render(refs, byDesign.vault_missing);
    assert.equal(link.hidden, true, 'Vault already has it');
    render(refs, byDesign.missing);
    assert.equal(link.hidden, false);
    render(refs, byDesign.cached);
    assert.equal(link.hidden, true);
    assert.equal(refs.hint.hidden, true);
});

test('a message that repeats the picture writes nothing', async () => {
    const { block, refs } = page();
    render(refs, byDesign.tier_dl);
    const records = [];
    const mo = new dom.window.MutationObserver((r) => records.push(...r));
    mo.observe(block, { childList: true, subtree: true, attributes: true, characterData: true });
    render(refs, byDesign.tier_dl);
    await Promise.resolve();
    mo.disconnect();
    assert.deepEqual(records, [], 'an identical second is not a single DOM write');
});

test('the plan: the player decides the variant; the server sends all three', () => {
    const view = byDesign.tier_dl.status.view;
    let p = present(view, { player: 'none' });
    assert.equal(p.key, 'tier_dl');
    assert.equal(p.ctx, 'download');
    assert.equal(p.box.title, view.plan.download.box.title);
    assert.equal(p.box.cta.label, 'Скачать до 10 раз быстрее');
    assert.equal(p.hint, '');

    p = present(view, { player: 'playing' });
    assert.equal(p.key, 'stream_ok');
    assert.equal(p.box, null, 'smooth playback sells nothing');
    assert.equal(p.hint, 'Без подписки — до 5 Мбит/с. Видео идёт без остановок.');
    assert.equal(p.viewerTone, 'flow', 'and the link to the viewer is cyan');

    p = present(view, { player: 'buffering' });
    assert.equal(p.key, 'stream_stall');
    assert.equal(p.ctx, 'stream');
    assert.equal(p.box.title, 'Видео подгружается медленнее, чем играет');
    assert.equal(p.box.sub, 'Без подписки — до 5 Мбит/с', 'the stream cannot know the bitrate');
    assert.equal(p.box.cta.label, 'Смотреть без ограничения скорости');

    // The player's own line, from the stream job, knows it.
    p = present(view, { player: 'buffering', stallSub: byDesign.stream_stall.stallSub });
    assert.equal(p.box.sub, 'Без подписки — до 5 Мбит/с, а файлу нужно 8 Мбит/с');

    // Cached and Vault keep their keys for a download and share the stream ones.
    assert.equal(present(byDesign.cached_tier.status.view, {}).key, 'cached_tier');
    assert.equal(present(byDesign.vaulted_tier.status.view, {}).key, 'vaulted_tier');
    assert.equal(present(byDesign.vaulted_tier.status.view, { player: 'buffering' }).key, 'stream_stall');
    assert.equal(present(byDesign.cached_tier.status.view, { player: 'playing' }).key, 'stream_ok');
});

// The cap's first seconds, before it has held long enough for the box
// (statusview.PlanBoxAfter): the pink link says the cap, and nothing is sold
// yet -- no box, and no line standing in for it either, or the block would
// grow twice (a line, then the box). A player that plays fine gets its fact
// as always; one buffering nothing yet, whatever the stream job estimated.
test('the cap before the box is due: the pink link, no box and no line in its place', () => {
    const view = byDesign.tier_fact.status.view;
    const stallSub = 'Без подписки — до 5 Мбит/с, а файлу нужно 8 Мбит/с';
    for (const env of [{}, { player: 'buffering', stallSub }, { upsellElsewhere: true }, { player: 'buffering', stallSub, upsellElsewhere: true }]) {
        const p = present(view, env);
        assert.equal(p.box, null, JSON.stringify(env));
        assert.equal(p.hint, '', `${JSON.stringify(env)}: nothing stands in for the box`);
    }
    assert.equal(present(view, {}).key, 'tier_dl');
    assert.equal(present(view, { player: 'buffering' }).key, 'stream_stall');
    const ok = present(view, { player: 'playing' });
    assert.equal(ok.key, 'stream_ok');
    assert.equal(ok.hint, view.plan.fact);
    assert.equal(ok.hint.replaceAll('\u00a0', ' '), 'Без подписки — до 5 Мбит/с. Видео идёт без остановок.');
    const fits = present(view, { player: 'buffering', fitsCap: true });
    assert.equal(fits.box, null);
    assert.equal(fits.hint, '', 'a file marked "fits": nothing stands in for the box either');

    // Drawn: the pink link, the box and the line hidden; then the box comes
    // into the same nodes.
    const { block, refs } = page();
    render(refs, byDesign.tier_fact);
    const viewer = block.querySelectorAll('[data-tx-seg]')[1];
    assert.equal(viewer.getAttribute('data-tone'), 'plan');
    assert.equal(viewer.querySelector('.tx-note').textContent, '· потолок');
    assert.equal(block.querySelector('[data-tx-hint]').hidden, true);
    assert.ok(Array.from(block.querySelectorAll('[data-tx-pbox]')).every((b) => b.hidden));
    const before = Array.from(block.querySelectorAll('*'));
    render(refs, byDesign.tier_dl);
    assert.equal(block.querySelector('[data-tx-pbox]').hidden, false);
    const now = Array.from(block.querySelectorAll('*'));
    assert.ok(now.length === before.length && now.every((el, i) => el === before[i]), 'the same nodes');
});

test('one offer at a time: with another on screen the box gives way to its line', () => {
    const view = byDesign.tier_dl.status.view;
    let p = present(view, { upsellElsewhere: true });
    assert.equal(p.box, null);
    assert.equal(p.hint, 'Скорость скачивания ограничена: 5 Мбит/с');
    assert.equal(p.hintTone, 'plan');
    p = present(view, { upsellElsewhere: true, player: 'buffering', stallSub: 'X, а файлу нужно 8' });
    assert.equal(p.box, null);
    assert.equal(p.hint, 'X, а файлу нужно 8');
});

test('nothing to sell: the server sends the fact alone and no button is drawn', () => {
    const view = structuredClone(byDesign.tier_dl.status.view);
    view.plan.download = { hint: 'Скорость скачивания ограничена: 5 Мбит/с' };
    view.plan.stream = { hint: 'Без подписки — до 5 Мбит/с' };
    let p = present(view, {});
    assert.equal(p.box, null);
    assert.equal(p.hint, 'Скорость скачивания ограничена: 5 Мбит/с');
    p = present(view, { player: 'buffering', stallSub: 'Без подписки — до 5 Мбит/с, а файлу нужно 8 Мбит/с' });
    assert.equal(p.hint, 'Без подписки — до 5 Мбит/с, а файлу нужно 8 Мбит/с');
});

test('a link that is not ours or https never becomes an href', () => {
    assert.equal(safeHref('/ru/trial?from=status-bar'), '/ru/trial?from=status-bar');
    assert.equal(safeHref('https://pay.example/x'), 'https://pay.example/x');
    for (const bad of ['javascript:alert(1)', '//evil.example', 'http://pay.example', '', null]) assert.equal(safeHref(bad), '', String(bad));
    const view = structuredClone(byDesign.tier_dl.status.view);
    view.plan.download.box.cta.url = 'javascript:alert(1)';
    assert.equal(present(view, {}).box, null);
});

test('stream_ok on the page: cyan link to the viewer with the cap noted, the fact, no box', () => {
    const { block, refs } = page();
    render(refs, byDesign.stream_ok);
    assert.equal(block.getAttribute('data-key'), 'stream_ok');
    const viewer = block.querySelectorAll('[data-tx-seg]')[1];
    assert.equal(viewer.getAttribute('data-tone'), 'flow');
    assert.ok(viewer.hasAttribute('data-moving'));
    assert.equal(viewer.querySelector('.tx-note').textContent, '· потолок');
    assert.equal(block.querySelector('[data-tx-htext]').textContent, 'Без подписки — до 5 Мбит/с. Видео идёт без остановок.');
    assert.ok(Array.from(block.querySelectorAll('[data-tx-pbox]')).every((b) => b.hidden));
    // Buffering again: the pink cap and the stream box, with its props.
    render(refs, byDesign.stream_stall);
    assert.equal(viewer.getAttribute('data-tone'), 'plan');
    const box = block.querySelector('[data-tx-pbox]');
    assert.equal(box.hidden, false);
    assert.deepEqual(ctaProps(box.querySelector('[data-tx-cta]')), {
        ctx: 'stream', location: 'card', auth: 'anon', state: 'stream_stall', tier: 'free', target: 'trial',
    });
    assert.equal(box.querySelector('[data-tx-ps]').textContent, 'Без подписки — до 5 Мбит/с, а файлу нужно 8 Мбит/с');
});

test('the piece bar: cells made once, filled and pulsing from the message; the divider keeps them', () => {
    const { refs } = page();
    render(refs, byDesign.active);
    assert.equal(refs.bar.getAttribute('data-mode'), 'pieces');
    assert.equal(refs.bar.getAttribute('data-tone'), 'flow');
    const cells = refs.cells.slice();
    // debug_pieces=stream: the head complete, 96..103 being fetched.
    assert.equal(cells[0].style.getPropertyValue('--fill'), '1.00');
    assert.equal(cells[40].style.getPropertyValue('--fill'), '0.00');
    assert.equal(cells[96].classList.contains('a'), true);
    assert.equal(cells[95].classList.contains('a'), false);
    assert.equal(refs.cellsHost.getAttribute('aria-label'), '40 из 1024 кусков на сервере');
    render(refs, byDesign.vaulting);
    assert.equal(refs.bar.getAttribute('data-tone'), 'vault');
    render(refs, byDesign.cached);
    assert.equal(refs.bar.getAttribute('data-mode'), 'divider');
    assert.equal(refs.cellsHost.children.length, 256, 'hidden, not thrown away');
    render(refs, byDesign.active);
    assert.ok(refs.cells.every((c, i) => c === cells[i]));
    // A view that wants the bar but a message without cells: the divider.
    const bare = structuredClone(byDesign.active);
    delete bare.status.pieces;
    render(refs, bare);
    assert.equal(refs.bar.getAttribute('data-mode'), 'divider');
});

test('the sticky copy: the same markup, ids of its own, its buttons and its description following them', () => {
    const { block } = page();
    const host = document.querySelector('[data-status-mirror-for]');
    const clone = mirrorBlock(block, host);
    assert.equal(host.firstElementChild, clone);
    assert.equal(clone.outerHTML.replaceAll('tx-details-sticky', 'tx-details').replaceAll('tx-bdesc-sticky', 'tx-bdesc'), block.outerHTML, 'nothing else differs');
    const ids = Array.from(document.querySelectorAll('[id]')).map((el) => el.id);
    assert.equal(new Set(ids).size, ids.length, 'no id twice on the page');
    assert.equal(clone.querySelector('[data-tx-toggle]').getAttribute('popovertarget'), 'tx-details-sticky');
    assert.equal(clone.querySelector('[data-tx-close]').getAttribute('popovertarget'), 'tx-details-sticky');
    // The chain is described by its own block's badge, not the card's.
    const desc = clone.querySelector('[data-tx-toggle]').getAttribute('aria-describedby');
    assert.equal(desc, 'tx-bdesc-sticky');
    assert.equal(document.getElementById(desc).closest('[data-tx]'), clone);
    assert.equal(document.getElementById(block.querySelector('[data-tx-toggle]').getAttribute('aria-describedby')).closest('[data-tx]'), block);
    assert.equal(document.querySelector('#torrent-status-sticky').textContent.includes('Sintel.2010'), false, 'no torrent name');
    // Bound and updated on its own, with its own location.
    const refs = bindBlock(clone);
    const st = byDesign.tier_dl;
    applyView(refs, st.status.view, present(st.status.view, {}), 'sticky');
    assert.equal(ctaProps(clone.querySelector('[data-tx-cta]')).location, 'sticky');
});

