test('details with the Popover API: placed under the chain, aria-expanded follows, closed when the chain leaves', () => {
    const { refs } = page();
    const { toggle, details } = refs;
    let open = false;
    details.showPopover = () => { open = true; };
    details.hidePopover = () => {
        open = false;
        details.dispatchEvent(Object.assign(new window.Event('toggle'), { newState: 'closed' }));
    };
    let rect = { left: 40, top: 300, bottom: 322, width: 500, height: 22 };
    toggle.getBoundingClientRect = () => rect;
    details.getBoundingClientRect = () => ({ width: 480, height: 200 });
    window.innerWidth = 390;
    window.innerHeight = 800;
    const stop = initDetails(refs, window);
    details.dispatchEvent(Object.assign(new window.Event('beforetoggle'), { newState: 'open' }));
    details.dispatchEvent(Object.assign(new window.Event('toggle'), { newState: 'open' }));
    assert.equal(toggle.getAttribute('aria-expanded'), 'true');
    assert.equal(details.style.top, '330px', 'under the chain');
    assert.equal(details.style.left, '8px', 'kept on a 390px screen');
    // Near the bottom: above the chain instead.
    rect = { left: 40, top: 700, bottom: 722, width: 300, height: 22 };
    window.dispatchEvent(new window.Event('resize'));
    assert.equal(details.style.top, '492px');
    // Fits neither way: the roomier side, scrolling inside, never over the chain.
    rect = { left: 40, top: 300, bottom: 322, width: 300, height: 22 };
    details.getBoundingClientRect = () => ({ width: 480, height: 700 });
    window.dispatchEvent(new window.Event('resize'));
    assert.equal(details.style.top, '330px');
    assert.equal(details.style.maxHeight, '462px');
    details.getBoundingClientRect = () => ({ width: 480, height: 200 });
    window.dispatchEvent(new window.Event('resize'));
    assert.equal(details.style.maxHeight, '', 'and no limit once it fits');
    // Scrolled away: closed.
    rect = { left: 40, top: -80, bottom: -58, width: 300, height: 22 };
    window.dispatchEvent(new window.Event('scroll'));
    assert.equal(open, false);
    assert.equal(toggle.getAttribute('aria-expanded'), 'false');
    stop();
});

// Popover-API stubs for a block: `open` follows show/hide, the chain's and
// the box's rects are the test's.
function popover(refs) {
    const { toggle, details } = refs;
    const st = { open: false, rect: { left: 40, top: 300, bottom: 322, width: 300, height: 22 }, box: { width: 480, height: 700 } };
    details.showPopover = () => { st.open = true; };
    details.hidePopover = () => {
        st.open = false;
        details.dispatchEvent(Object.assign(new window.Event('toggle'), { newState: 'closed' }));
    };
    toggle.getBoundingClientRect = () => st.rect;
    details.getBoundingClientRect = () => st.box;
    st.show = () => {
        details.dispatchEvent(Object.assign(new window.Event('beforetoggle'), { newState: 'open' }));
        details.dispatchEvent(Object.assign(new window.Event('toggle'), { newState: 'open' }));
        st.open = true;
    };
    return st;
}

// A box taller than the room scrolls inside. Its own scroll events reach the
// window's capture listener too; re-placing on them lifted the cap to
// measure, which clamps the box's scroll to the top -- every wheel tick
// snapped it back and its end was never readable.
test('details: the box scrolls inside without being snapped back to its top', () => {
    const { refs } = page();
    const { details } = refs;
    const st = popover(refs);
    window.innerWidth = 390;
    window.innerHeight = 664;
    let scrollTop = 0;
    Object.defineProperty(details, 'scrollTop', { configurable: true, get: () => scrollTop, set: (v) => { scrollTop = v; } });
    // Layout without the cap: the box fits, so the browser clamps its scroll.
    details.getBoundingClientRect = () => {
        if (details.style.maxHeight === '') scrollTop = 0;
        return st.box;
    };
    const stop = initDetails(refs, window);
    st.show();
    assert.equal(details.style.maxHeight, '326px', 'capped, scrolling inside');
    scrollTop = 120;
    details.dispatchEvent(new window.Event('scroll'));
    assert.equal(scrollTop, 120, 'its own scroll is not a move of the chain');
    // The page scrolls: re-placed, and the box keeps where it was.
    st.rect = { ...st.rect, top: 290, bottom: 312 };
    window.dispatchEvent(new window.Event('scroll'));
    assert.equal(details.style.top, '320px');
    assert.equal(scrollTop, 120, 'the page\'s scroll does not reset the box\'s');
    stop();
});

