// The stream job's "fits" is an estimate; a real stall while the server says
// the limiter binds (the box is due only after thp held the viewer at the cap
// for 8 s) is the cap's doing whatever it estimated. Recorded 2026-09-26:
// The Knick, marked "fits" at 4.34 of 5, pulled 5.04 and stalled four times
// in 180 s -- the page said the cap line alone and sold nothing, the owner's
// complaint once more. "Fits" keeps its playing-case meaning only: no line.
test('a file marked "fits" stalling at the cap: the stream box, like any stall', () => {
    const view = byDesign.tier_dl.status.view;
    assert.ok(view.plan.stream.box, 'the server says the box is due');
    const capOnly = 'Без подписки — до 5 Мбит/с';
    const p = present(view, { player: 'buffering', fitsCap: true, stallSub: capOnly });
    assert.equal(p.key, 'stream_stall');
    assert.equal(p.ctx, 'stream');
    assert.ok(p.box, 'the box');
    assert.equal(p.box.title, 'Видео подгружается медленнее, чем играет');
    assert.equal(p.box.sub, capOnly, 'the cap alone: never "needs 4.6" next to "up to 5"');
    assert.equal(p.box.cta.label, 'Смотреть без ограничения скорости');
    assert.equal(p.hint, '');
    // The same as a file of unknown bitrate stalling.
    const unknown = present(view, { player: 'buffering', stallSub: capOnly });
    assert.deepEqual(p, unknown);
    // Playing smoothly: nothing under the bar, as before.
    const ok = present(view, { player: 'playing', fitsCap: true, stallSub: capOnly });
    assert.equal(ok.box, null);
    assert.equal(ok.hint, '');
    // Another offer on screen: the box gives way to its line.
    const other = present(view, { player: 'buffering', fitsCap: true, stallSub: capOnly, upsellElsewhere: true });
    assert.equal(other.box, null);
    assert.equal(other.hint, capOnly);
    assert.equal(other.hintTone, 'plan');
    // Inside the grace window nothing is sold, "fits" or not.
    const grace = present(view, { player: 'buffering', fitsCap: true, stallSub: capOnly, inGrace: true });
    assert.equal(grace.box, null);
    assert.equal(grace.hint, view.plan.cap);
    assert.equal(present(view, { player: 'none', fitsCap: true }).box !== null, true, 'a download is still sold');
});

// The owner's rule for a player that plays (2026-09-25/26): its file over the
// cap -- the stream box as soon as the server says it is due, without waiting
// for the first stall (the grace buffer hides the cap for minutes, and at the
// cap the stall is inevitable); its file under the cap -- no line at all, the
// pink link to the viewer as always; its bitrate unknown -- the fact, and the
// box at the first real stall, as before.
test('a player playing: the box for a file over the cap, nothing for one under it, the fact when unknown', () => {
    const view = byDesign.tier_dl.status.view;
    const stallSub = 'Без подписки — до 5 Мбит/с, а файлу нужно 8 Мбит/с';
    let p = present(view, { player: 'playing', overCap: true, stallSub });
    assert.equal(p.key, 'stream_over');
    assert.equal(p.ctx, 'stream');
    assert.equal(p.box.title, 'Видео подгружается медленнее, чем играет');
    assert.equal(p.box.sub, stallSub, 'what the file needs, from the stream job');
    assert.equal(p.box.cta.label, 'Смотреть без ограничения скорости');
    assert.equal(p.hint, '');
    assert.equal(p.viewerTone, '', 'the pink cap, as with the stream box at a stall');
    // Buffering, it is the stall's box as before.
    assert.equal(present(view, { player: 'buffering', overCap: true, stallSub }).key, 'stream_stall');

    p = present(view, { player: 'playing', fitsCap: true, stallSub: 'Без подписки — до 5 Мбит/с' });
    assert.equal(p.key, 'stream_ok');
    assert.equal(p.box, null);
    assert.equal(p.hint, '', 'no line: not the fact, not the cap');
    assert.equal(p.viewerTone, 'flow', 'the link to the viewer as it is: cyan, the cap noted');

    p = present(view, { player: 'playing' });
    assert.equal(p.key, 'stream_ok');
    assert.equal(p.box, null);
    assert.equal(p.hint.replaceAll('\u00a0', ' '), 'Без подписки — до 5 Мбит/с. Видео идёт без остановок.', 'unknown: the fact');

    // Before the box is due: the pink link, and nothing under the bar in
    // its place -- not the fact, which it would contradict in a minute.
    const fact = byDesign.tier_fact.status.view;
    p = present(fact, { player: 'playing', overCap: true, stallSub });
    assert.equal(p.key, 'stream_over');
    assert.equal(p.box, null);
    assert.equal(p.hint, '');
    assert.equal(p.viewerTone, '');
    // Another offer on screen (the grace popup): the box gives way to its line.
    p = present(view, { player: 'playing', overCap: true, stallSub, upsellElsewhere: true });
    assert.equal(p.box, null);
    assert.equal(p.hint, stallSub);
    assert.equal(p.hintTone, 'plan');
    // No player: the download box, whatever the job said of the file.
    assert.equal(present(view, { overCap: true }).key, 'tier_dl');
});

// The grace window is not the plan's cap: while the page's player is inside
// it by movie time, nothing is sold -- though the server's verdict can be on
// there, from the tier's segments hls.js fetches ahead past the window at
// the cap (recorded 2026-09-26: the box was due 6.7 s before the player left
// a 30 s window).
test('inside the grace window: no box, no line that sells, whatever the server says', () => {
    const view = byDesign.tier_dl.status.view;
    assert.ok(view.plan.stream.box, 'the server says the box is due');
    const stallSub = 'Без подписки — до 5 Мбит/с, а файлу нужно 8 Мбит/с';
    for (const env of [
        { player: 'playing', overCap: true, stallSub },
        { player: 'playing', fitsCap: true },
        { player: 'playing' },
        { player: 'buffering', overCap: true, stallSub },
        { player: 'buffering', fitsCap: true },
        { player: 'buffering' },
    ]) {
        const p = present(view, { ...env, inGrace: true });
        assert.equal(p.box, null, JSON.stringify(env));
        assert.notEqual(p.hintTone, 'plan', JSON.stringify(env));
        assert.ok(!p.hint.includes('нужно'), `${JSON.stringify(env)}: ${p.hint}`);
    }
    assert.equal(present(view, { player: 'playing', overCap: true, inGrace: true }).hint, '', 'over the cap: no fact either');
    assert.equal(present(view, { player: 'playing', inGrace: true }).hint, view.plan.fact, 'unknown: the fact');
    assert.equal(present(view, { player: 'buffering', inGrace: true }).hint, view.plan.cap, 'waiting: the cap, nothing sold');
    // Past the window: the box.
    assert.ok(present(view, { player: 'playing', overCap: true, stallSub, inGrace: false }).box);
    // A download is not in any grace window.
    assert.ok(present(view, { player: 'none', inGrace: true }).box);
});

// The owner's flow (2026-09-26): leaving the grace window the popup tells the
// viewer the cap is coming; they answer "continue at N Mbps" (or close it).
// They have just been told: a file over the cap is not sold again until they
// hit the cap -- the player's first real stall -- and nothing stands under the
// bar meanwhile (the fact's "no stops" is false for it). In Chrome the box
// came 0.5 s after the popup closed: thp binds on the segments past the
// window, so the server's box was due before the popup went.
test('the grace popup answered: a file over the cap is not sold until it stalls', () => {
    const view = byDesign.tier_dl.status.view;
    assert.ok(view.plan.stream.box, 'the server says the box is due');
    const stallSub = 'Без подписки — до 5 Мбит/с, а файлу нужно 8 Мбит/с';
    const quiet = { key: 'stream_over', ctx: 'stream', hint: '', hintTone: '', box: null, viewerTone: '' };
    const pick = (p) => ({ key: p.key, ctx: p.ctx, hint: p.hint, hintTone: p.hintTone, box: p.box, viewerTone: p.viewerTone });
    // Playing, answered: no box, no line, the pink link says the cap -- as
    // before the box is due.
    assert.deepEqual(pick(present(view, { player: 'playing', overCap: true, stallSub, offerAnswered: true })), quiet);
    const notDue = present(byDesign.tier_fact.status.view, { player: 'playing', overCap: true, stallSub });
    assert.deepEqual(pick(notDue), quiet, 'the same picture as a box not yet due');
    // 'buffering' with the answer standing is the minute after a stall that
    // ended before it (playerActivity offerAnswered): still the popup's.
    assert.deepEqual(pick(present(view, { player: 'buffering', overCap: true, stallSub, offerAnswered: true })), quiet);
    // The first real stall spends the answer: the stream box as at any
    // capped stall, and the over-cap rule after it.
    let p = present(view, { player: 'buffering', overCap: true, stallSub, offerAnswered: false });
    assert.equal(p.key, 'stream_stall');
    assert.ok(p.box);
    assert.equal(p.box.sub, stallSub);
    p = present(view, { player: 'playing', overCap: true, stallSub, offerAnswered: false });
    assert.equal(p.key, 'stream_over');
    assert.ok(p.box, 'no popup at all (paid tiers, grace off), or its answer spent: the box once due');
    // Unknown and "fits" keep their rules: nothing to sell while they play,
    // the box at a real stall.
    assert.equal(present(view, { player: 'playing', offerAnswered: true }).hint, view.plan.fact, 'unknown: the fact');
    assert.equal(present(view, { player: 'playing', fitsCap: true, offerAnswered: true }).hint, '');
    assert.ok(present(view, { player: 'buffering', offerAnswered: true }).box, 'unknown stalling: the box');
    assert.ok(present(view, { player: 'buffering', fitsCap: true, offerAnswered: true }).box, '"fits" stalling: the box');
    // A download is not the player's.
    assert.equal(present(view, { player: 'none', overCap: true, offerAnswered: true }).key, 'tier_dl');
    assert.ok(present(view, { player: 'none', overCap: true, offerAnswered: true }).box);
    // Inside a grace window (a seek back into it): as ever.
    assert.equal(present(view, { player: 'playing', overCap: true, inGrace: true, offerAnswered: true }).key, 'stream_ok');
});

// Between two HLS segments the proxy counts no request of the viewer's open,
// and past the debounce the server's view has nobody on the chain -- here
// the badge of cached content. It sends the view with the viewer at their
// last reading next to it; the page draws that while its own player plays:
// the same nodes, only shown.
test('playing: the server\'s view with the viewer at their last reading, the same nodes', () => {
    const { block, refs } = page();
    const view = byDesign.hls_gap.status.view;
    assert.equal(view.key, 'cached');
    assert.equal(view.mode, 'badge', 'nobody\'s requests are open: nothing moves');
    assert.ok(view.playing, 'the server sends the alternative');
    const p = playing(view);
    assert.equal(p.key, 'cached_flow');
    assert.equal(p.mode, 'chain');
    assert.equal(p.sticky, true);
    assert.equal(p.nodes[2].show, true);
    assert.equal(p.segs[1].show, true);
    assert.equal(p.playing, null);
    const before = Array.from(block.querySelectorAll('*'));
    applyView(refs, view, present(view, { player: 'playing' }), 'card');
    assert.equal(block.getAttribute('data-mode'), 'badge');
    applyView(refs, p, present(p, { player: 'playing' }), 'card');
    assert.equal(block.getAttribute('data-mode'), 'chain');
    assert.equal(block.getAttribute('data-key'), 'cached_flow');
    assert.equal(block.querySelectorAll('[data-tx-node]')[2].hidden, false);
    assert.equal(block.querySelectorAll('[data-tx-seg]')[1].querySelector('.tx-spd').textContent, '24\u00a0Мбит/с');
    const now = Array.from(block.querySelectorAll('*'));
    assert.ok(now.length === before.length && now.every((el, i) => el === before[i]), 'the same nodes');
    assert.equal(playing(byDesign.active.status.view), byDesign.active.status.view, 'no alternative: the view itself');
});

