test('impression: half on screen for a second, once per set of props, not for a hidden box', (t) => {
    t.mock.timers.enable({ apis: ['setTimeout'] });
    const { block, refs } = page();
    const tracked = [];
    const umami = { track: (name, props) => tracked.push([name, props]) };
    let io;
    class IO {
        constructor(cb) { this.cb = cb; this.targets = []; io = this; }
        observe(el) { this.targets.push(el); }
        disconnect() { this.targets = []; }
        fire(el, ratio) { this.cb([{ target: el, isIntersecting: ratio > 0, intersectionRatio: ratio }]); }
    }
    const watch = createCtaWatch({ umami, IO, registry: new Set() });
    const a = block.querySelector('[data-tx-cta]');
    watch.watch(a);

    // Not a plan state: the box is hidden, nothing to count.
    render(refs, byDesign.active);
    io.fire(a, 1);
    t.mock.timers.tick(1500);
    assert.deepEqual(tracked, []);

    render(refs, byDesign.tier_dl);
    watch.refresh();
    t.mock.timers.tick(999);
    assert.deepEqual(tracked, [], 'not before a second');
    t.mock.timers.tick(1);
    assert.deepEqual(tracked, [['donate-status-bar-shown', { ctx: 'download', location: 'card', auth: 'anon', state: 'tier_dl', tier: 'free', target: 'trial' }]]);

    // Scrolled off at 40% and back: the same offer is not a second impression.
    io.fire(a, 0.4);
    io.fire(a, 0.8);
    t.mock.timers.tick(2000);
    assert.equal(tracked.length, 1);

    // The player starts buffering while it is on screen: another offer.
    render(refs, byDesign.stream_stall);
    watch.refresh();
    t.mock.timers.tick(1000);
    assert.equal(tracked.length, 2);
    assert.equal(tracked[1][1].ctx, 'stream');
    assert.equal(tracked[1][1].state, 'stream_stall');

    // Seen for half a second only: nothing.
    render(refs, byDesign.cached_tier);
    io.fire(a, 0);
    io.fire(a, 0.6);
    t.mock.timers.tick(500);
    io.fire(a, 0.1);
    t.mock.timers.tick(2000);
    assert.equal(tracked.length, 2);
    watch.stop();
});

