test('impression: the two boxes of one block (under the bar, in the details) seen together count once', (t) => {
    t.mock.timers.enable({ apis: ['setTimeout'] });
    const { block, refs } = page();
    const tracked = [];
    let io;
    class IO {
        constructor(cb) { this.cb = cb; io = this; }
        observe() {}
        disconnect() {}
        fire(el, ratio) { this.cb([{ target: el, isIntersecting: ratio > 0, intersectionRatio: ratio }]); }
    }
    const watch = createCtaWatch({ umami: { track: (n, p) => tracked.push([n, p]) }, IO, registry: new Set() });
    const [inBlock, inDetails] = Array.from(block.querySelectorAll('[data-tx-cta]'));
    watch.watch(inBlock);
    watch.watch(inDetails);
    render(refs, byDesign.tier_dl);
    assert.deepEqual(ctaProps(inBlock), ctaProps(inDetails), 'the same offer, the same props');
    io.fire(inBlock, 1);
    io.fire(inDetails, 1);
    t.mock.timers.tick(1000);
    assert.equal(tracked.length, 1, 'one offer on screen, one impression');
    watch.stop();
});
